mapper.select:
select id, task_no as taskNo, plan_id as planId, plan_name_snapshot as planName, inspector_id as inspectorId, inspector_name_snapshot as inspectorName, task_date as taskDate, deadline_at as deadlineAt, status, equipment_count as equipmentCount, completed_equipment_count as completedEquipmentCount, started_at as startedAt, completed_at as completedAt from inspection_task
and task_no like concat('%', #{taskNo}, '%')
and inspector_id = #{inspectorId}
and status = #{status}
and task_date >= #{taskDateFrom}
and task_date <= #{taskDateTo}
order by task_date desc, id desc

select id, task_no as taskNo, plan_id as planId, plan_name_snapshot as planName, inspector_id as inspectorId, inspector_name_snapshot as inspectorName, task_date as taskDate, deadline_at as deadlineAt, status, equipment_count as equipmentCount, completed_equipment_count as completedEquipmentCount, started_at as startedAt, completed_at as completedAt from inspection_task where inspector_id = #{inspectorId} and task_date = #{taskDate}
and status = #{status}
order by id desc

select id as task_equipment_id, equipment_id
from inspection_task_equipment
where task_id = #{taskId}

mapper.update:
update inspection_task_equipment
set completion_status = 'COMPLETED', completed_at = #{completedAt}
where task_id = #{taskId} and completion_status = 'PENDING'

mapper.select:
select exists(
    select 1 from inspection_task
    where plan_id = #{planId} and task_date = #{taskDate}
)

mapper.update:
update inspection_task
set status = 'OVERDUE', version = version + 1
where status = 'PENDING' and deadline_at < #{now}
